1	package agents
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"regexp"
11		"runtime"
12		"strings"
13		"time"
14	)
15	
16	func init() {
17		if env := os.Getenv("E2E_AGENT"); env != "" && env != "copilot-cli" {
18			return
19		}
20		Register(&CopilotCLI{})
21		RegisterGate("copilot-cli", 4)
22	}
23	
24	type CopilotCLI struct{}
25	
26	// copilotPromptPattern matches Copilot's idle input area. v1.0.81 removed the
27	// bare "❯" marker in favour of a bordered box, leaving the footer hints row as
28	// the only stable text to key on.
29	//
30	// That row is idle-only, which makes it a real readiness signal rather than
31	// always-on chrome: in the v1.0.81 bundle the footer renders either the
32	// activity indicator or the hints row and never both, so "← open sidebar"
33	// disappears for the duration of a turn. (Read from the shipped bundle, not
34	// observed live — and the indicator is suppressed under one condition that was
35	// not traced, so treat it as strong evidence rather than a guarantee.)
36	//
37	// It says nothing about modals, though: a startup dialog or the session-restore
38	// picker keeps the row while the agent is not accepting input, which is what
39	// copilotPromptReady exists to reject.
40	const copilotPromptPattern = `(?m:^[^\S\n]*❯[^\S\n]*$)|← open sidebar`
41	
42	var copilotPromptRegexp = regexp.MustCompile(copilotPromptPattern)
43	
44	func (c *CopilotCLI) Name() string               { return "copilot-cli" }
45	func (c *CopilotCLI) Binary() string             { return "copilot" }
46	func (c *CopilotCLI) EntireAgent() string        { return "copilot-cli" }
47	func (c *CopilotCLI) PromptPattern() string      { return copilotPromptPattern }
48	func (c *CopilotCLI) TimeoutMultiplier() float64 { return 1.5 }
49	
50	func (c *CopilotCLI) IsTransientError(out Output, err error) bool {
51		if errors.Is(err, context.DeadlineExceeded) {
52			return true
53		}
54		combined := out.Stdout + out.Stderr
55		for _, p := range []string{
56			"overloaded",
57			"rate limit",
58			"503",
59			"529",
60			"ECONNRESET",
61			"ETIMEDOUT",
62			"Too Many Requests",
63			// Copilot sometimes calls its Edit tool without old_str,
64			// resulting in zero code changes despite a successful exit.
65			"old_str is required",
66		} {
67			if strings.Contains(combined, p) {
68				return true
69			}
70		}
71		return false
72	}
73	
74	func (c *CopilotCLI) Bootstrap() error {
75		// Copilot CLI uses GitHub authentication (gh auth or GITHUB_TOKEN).
76		// No additional bootstrap needed — auth should be pre-configured.
77		return nil
78	}
79	
80	func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
81		cfg := &runConfig{Model: "claude-haiku-4.5"}
82		for _, o := range opts {
83			o(cfg)
84		}
85	
86		timeout, err := promptTimeout(60*time.Second, cfg)
87		if err != nil {
88			return Output{}, err
89		}
90		promptCtx, cancel := context.WithTimeout(ctx, timeout)
91		defer cancel()
92	
93		args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
94		displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
95		cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
96		cmd.Dir = dir
97		cmd.Stdin = nil
98		// GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS opts in to .github/hooks/*.json loading
99		// in -p mode; gated since Copilot 1.0.40 (2026-05-01).
100		// Unlike StartSession, this leaves the caller's COPILOT_HOME alone: the
101		// session collisions that forced interactive mode onto an isolated home
102		// come from the restore picker, which -p mode never shows.
103		cmd.Env = append(os.Environ(),
104			"ENTIRE_TEST_TTY=0",
105			"GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS=true",
106		)
107		setupProcessGroup(cmd)
108		cmd.WaitDelay = 5 * time.Second
109	
110		var stdout, stderr strings.Builder
111		cmd.Stdout = &stdout
112		cmd.Stderr = &stderr
113	
114		exitCode, err := runCapture(cmd, promptCtx)
115	
116		out := Output{
117			Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
118			Stdout:   stdout.String(),
119			Stderr:   stderr.String(),
120			ExitCode: exitCode,
121		}
122	
123		// Copilot sometimes calls its Edit tool without required parameters,
124		// producing zero code changes despite exit 0. Surface this as an error so
125		// the transient-error retry mechanism can restart the scenario.
126		// Only trigger when copilot reports zero changes — it may retry internally.
127		if err == nil && strings.Contains(out.Stdout, "old_str is required") &&
128			strings.Contains(out.Stderr, "Total code changes:     +0 -0") {
129			err = errors.New("copilot Edit tool failed: old_str is required")
130		}
131	
132		return out, err
133	}
134	
135	// CopilotSession wraps TmuxSession to handle Copilot CLI's dual input modes.
136	// Copilot CLI can be in "Chat" mode (Enter submits) or "Edit" mode (Ctrl+S
137	// submits). After completing a prompt, copilot may return to either mode
138	// non-deterministically. This wrapper detects Edit mode after sending Enter
139	// and falls back to Ctrl+S if needed.
140	type CopilotSession struct {
141		*TmuxSession
142	}
143	
144	func (cs *CopilotSession) Send(input string) error {
145		if err := cs.clearInputLine(); err != nil {
146			return err
147		}
148	
149		preSend := stableContent(cs.Capture())
150	
151		if err := cs.sendOnce(input, preSend); err != nil {
152			return err
153		}
154	
155		// Copilot CLI's autocomplete can non-deterministically trigger during
156		// text input (e.g. a "/" in "docs/red.md" opens the slash-command menu).
157		// If detected, dismiss with Escape, clear the input, and retry once.
158		time.Sleep(300 * time.Millisecond)
159		if isAutocompleteMenu(cs.Capture()) {
160			if err := cs.dismissAutocompleteAndClear(); err != nil {
161				return err
162			}
163			if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
164				return err
165			}
166		}
167	
168		// Copilot can leave behind a stray slash-command invocation between turns.
169		// Only retry if that error appeared in output produced by this submission,
170		// not merely somewhere in pane scrollback from an earlier turn.
171		if content := cs.Capture(); appearedInNewOutput(preSend, content, "Unknown command: /") {
172			if err := cs.clearInputLine(); err != nil {
173				return err
174			}
175			if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
176				return err
177			}
178		}
179	
180		// Wait for the terminal to reflect the echoed input, then snapshot.
181		deadline := time.Now().Add(5 * time.Second)
182		for time.Now().Before(deadline) {
183			time.Sleep(200 * time.Millisecond)
184			current := stableContent(cs.Capture())
185			if current != preSend {
186				cs.stableAtSend = current
187				return nil
188			}
189		}
190		cs.stableAtSend = stableContent(cs.Capture())
191		return nil
192	}
193	
194	// clearInputLine removes any partially typed prompt text without sending other
195	// UI navigation keys. In Copilot CLI, Escape can trigger undo/snapshot actions,
196	// so routine pre-send cleanup must avoid it.
197	func (cs *CopilotSession) clearInputLine() error {
198		if err := cs.SendKeys("C-u"); err != nil {
199			return err
200		}
201		time.Sleep(200 * time.Millisecond)
202		return nil
203	}
204	
205	// dismissAutocompleteAndClear closes the slash-command autocomplete dropdown
206	// and then clears the input line before retrying the prompt.
207	func (cs *CopilotSession) dismissAutocompleteAndClear() error {
208		if err := cs.SendKeys("Escape"); err != nil {
209			return err
210		}
211		time.Sleep(200 * time.Millisecond)
212		return cs.clearInputLine()
213	}
214	
215	// appearedInNewOutput reports whether pattern is present in content that was
216	// added after the pre-send snapshot. This avoids retriggering on old pane
217	// scrollback from previous turns.
218	func appearedInNewOutput(before string, after string, pattern string) bool {
219		if after == before {
220			return false
221		}
222		if strings.HasPrefix(after, before) {
223			return strings.Contains(after[len(before):], pattern)
224		}
225	
226		// If tmux capture lost a clean prefix relationship due to scrollback churn,
227		// fall back to checking only the most recent lines.
228		lines := strings.Split(after, "\n")
229		start := max(0, len(lines)-12)
230		return strings.Contains(strings.Join(lines[start:], "\n"), pattern)
231	}
232	
233	// sendOnce types the input text, sends Enter, and handles Edit mode fallback.
234	func (cs *CopilotSession) sendOnce(input string, preSend string) error {
235		// Use -l (literal) flag to prevent tmux from interpreting characters
236		// in the prompt text as special key names.
237		args := []string{"send-keys", "-l", "-t", cs.name, input}
238		cmd := exec.Command("tmux", args...)
239		if out, err := cmd.CombinedOutput(); err != nil {
240			return fmt.Errorf("tmux send-keys -l: %w\n%s", err, out)
241		}
242		time.Sleep(200 * time.Millisecond)
243		if err := cs.SendKeys("Enter"); err != nil {
244			return err
245		}
246	
247		// Briefly poll to see if copilot is still in Edit mode (Enter didn't submit).
248		// In Edit mode the status bar shows "ctrl+s run command". If detected,
249		// send Ctrl+S to actually submit the prompt. Break early if the content
250		// changes from the pre-send snapshot, indicating submission has started.
251		editDeadline := time.Now().Add(500 * time.Millisecond)
252		for time.Now().Before(editDeadline) {
253			content := cs.Capture()
254			if isEditMode(content) {
255				if err := cs.SendKeys("C-s"); err != nil {
256					return err
257				}
258				break
259			}
260			if stableContent(content) != preSend {
261				break
262			}
263			time.Sleep(50 * time.Millisecond)
264		}
265		return nil
266	}
267	
268	// isEditMode checks if copilot-cli is in Edit mode by looking for the
269	// "ctrl+s run command" indicator in the last few lines (status bar area).
270	// Restricting the search avoids false positives if the phrase appears in
271	// agent output.
272	func isEditMode(content string) bool {
273		lines := strings.Split(content, "\n")
274		const statusPhrase = "ctrl+s run command"
275		for i := len(lines) - 1; i >= 0 && i >= len(lines)-3; i-- {
276			if strings.Contains(lines[i], statusPhrase) {
277				return true
278			}
279		}
280		return false
281	}
282	
283	// isAutocompleteMenu detects copilot's slash-command autocomplete dropdown.
284	// When triggered, copilot shows a list of commands starting with "▋  /"
285	// below the input line, preventing prompt submission.
286	func isAutocompleteMenu(content string) bool {
287		lines := strings.Split(content, "\n")
288		matches := 0
289		for _, line := range lines {
290			trimmed := strings.TrimSpace(line)
291			if strings.HasPrefix(trimmed, "▋") && strings.Contains(trimmed, "/") {
292				matches++
293				if matches >= 2 {
294					return true
295				}
296			}
297		}
298		return false
299	}
300	
301	// isStartupDialog reports whether the captured pane is showing a Copilot
302	// startup dialog (e.g. "Confirm folder trust") rather than the interactive
303	// prompt. The dialog renders its selected option with the same "❯" cursor as
304	// the input prompt, so presence of "❯" alone cannot distinguish them — we must
305	// key off the dialog chrome.
306	//
307	// Matching is case-insensitive and keyed off both the dialog title and its
308	// footer: Copilot v1.0.63 lowercased the footer to "enter to select", which
309	// silently broke the previous exact "Enter to select" match and caused the
310	// harness to mistake the trust dialog's "❯ 1. Yes" cursor for the prompt —
311	// breaking out of the dismissal loop without dismissing the dialog, so the
312	// first real prompt was swallowed by the still-open dialog.
313	func isStartupDialog(content string) bool {
314		lower := strings.ToLower(content)
315		return strings.Contains(lower, "confirm folder trust") ||
316			strings.Contains(lower, "do you trust") ||
317			strings.Contains(lower, "enter to select")
318	}
319	
320	func copilotPromptReady(content string) bool {
321		if isStartupDialog(content) || strings.Contains(strings.ToLower(content), "choose which sessions to restore") {
322			return false
323		}
324		return copilotPromptRegexp.MatchString(content)
325	}
326	
327	func resolveGHConfigDir(goos, home, explicit, xdgConfig, appData string) string {
328		if explicit != "" {
329			return explicit
330		}
331		if xdgConfig != "" {
332			return filepath.Join(xdgConfig, "gh")
333		}
334		if goos == "windows" && appData != "" {
335			return filepath.Join(appData, "GitHub CLI")
336		}
337		if home != "" {
338			return filepath.Join(home, ".config", "gh")
339		}
340		return ""
341	}
342	
343	func currentGHConfigDir() string {
344		home, _ := os.UserHomeDir()
345		return resolveGHConfigDir(
346			runtime.GOOS,
347			home,
348			os.Getenv("GH_CONFIG_DIR"),
349			os.Getenv("XDG_CONFIG_HOME"),
350			os.Getenv("AppData"),
351		)
352	}
353	
354	func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
355		bin, err := exec.LookPath(c.Binary())
356		if err != nil {
357			return nil, fmt.Errorf("agent binary not found: %w", err)
358		}
359	
360		// Give each interactive session its own Copilot state. Copilot stores all
361		// sessions under its home, so sharing one lets parallel tests see and
362		// attempt to restore one another's still-running sessions.
363		//
364		// COPILOT_HOME is Copilot's own documented override for that directory
365		// ("copilot help environment"), which is why it is used here in preference
366		// to replacing HOME: HOME also resolves ~/.gitconfig, ~/.ssh, tool caches
367		// and Entire's own ~/.config/entire for every hook the agent spawns, none
368		// of which this isolation is about. Entire's copilotcli.GetSessionDir
369		// honours COPILOT_HOME too, so the agent and the hooks agree on where the
370		// transcript lives.
371		sessionHome, err := os.MkdirTemp("", "copilot-e2e-home-*")
372		if err != nil {
373			return nil, fmt.Errorf("create isolated Copilot home: %w", err)
374		}
375	
376		// Forward auth into the tmux session, which starts a new shell that does
377		// not inherit os.Environ(). Copilot accepts COPILOT_GITHUB_TOKEN, GH_TOKEN
378		// and GITHUB_TOKEN in that order of precedence, and an env token outranks
379		// any stored credential; CI sets the first, local runs may have any of them.
380		envArgs := []string{"COPILOT_HOME=" + sessionHome}
381		for _, key := range []string{
382			"COPILOT_GITHUB_TOKEN", "GH_TOKEN", "GITHUB_TOKEN",
383			"HOME", "TERM", "XDG_CONFIG_HOME",
384		} {
385			if v := os.Getenv(key); v != "" {
386				envArgs = append(envArgs, key+"="+v)
387			}
388		}
389		// Not a Copilot variable — it is absent from "copilot help environment",
390		// and Copilot's own auth never consults gh's config. It is forwarded for
391		// the processes Copilot spawns: the GitHub MCP server and any `gh` the
392		// agent runs as a tool.
393		ghConfigDir := currentGHConfigDir()
394		if ghConfigDir != "" {
395			envArgs = append(envArgs, "GH_CONFIG_DIR="+ghConfigDir)
396		}
397		args := append([]string{"env"}, envArgs...)
398		args = append(args, bin, "--model", "claude-haiku-4.5", "--allow-all")
399	
400		name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
401		// Strip CI env vars that may affect interactive mode.
402		unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
403		s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
404		if err != nil {
405			_ = os.RemoveAll(sessionHome)
406			return nil, err
407		}
408		// Copilot's own logs live in this home, so keep it when a run is being
409		// debugged: Close() runs from artifact cleanup, which does not know
410		// whether the test failed.
411		s.OnClose(func() {
412			if os.Getenv("E2E_KEEP_AGENT_HOME") != "" {
413				fmt.Fprintf(os.Stderr, "copilot session home retained: %s\n", sessionHome)
414				return
415			}
416			_ = os.RemoveAll(sessionHome)
417		})
418	
419		// Dismiss startup dialogs (folder trust, etc.) then wait for the input prompt.
420		// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
421		// new directories. "Yes" is pre-selected, so Enter dismisses it.
422		foundPrompt := false
423		for range 5 {
424			content, err := s.WaitFor(`(?:`+c.PromptPattern()+`|(?i:enter to select))`, 30*time.Second)
425			if err != nil {
426				_ = s.Close()
427				return nil, fmt.Errorf("waiting for startup prompt: %w", err)
428			}
429			if copilotPromptReady(content) {
430				foundPrompt = true
431				break
432			}
433			if err := s.SendKeys("Enter"); err != nil {
434				_ = s.Close()
435				return nil, fmt.Errorf("dismissing startup dialog: %w", err)
436			}
437			time.Sleep(500 * time.Millisecond)
438		}
439		if !foundPrompt {
440			_ = s.Close()
441			return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
442		}
443		s.stableAtSend = ""
444	
445		return &CopilotSession{TmuxSession: s}, nil
446	}
